] === 'AdminEmpresa' ? 'disabled' : '' ?>><span><span class="block text-xs font-semibold text-slate-700"><?= e($definition[0]) ?></span><span class="mt-1 block text-[10px] leading-4 text-slate-400"><?= e($definition[1]) ?></span><code class="mt-1 block text-[9px] text-slate-400"><?= e($permission) ?></code></span></label><?php endforeach; ?></div><?php else: ?><p class="mt-3 rounded-xl bg-slate-50 p-3 text-xs text-slate-500">La cuenta de trabajador no recibe permisos de gestión ni acceso a expedientes reservados.</p><?php endif; ?></div><div class="mt-7 border-t border-slate-100 pt-6"><h2 class="text-sm font-semibold">Restablecer contraseña · opcional</h2><p class="mt-1 text-xs leading-5 text-slate-400">Déjala en blanco para conservar la actual. Si la restableces, la cuenta deberá cambiarla antes de usar los módulos.</p><?php if ($account['id'] === $user['id']): ?><div class="mt-3 rounded-xl bg-blue-50 p-3 text-[11px] leading-5 text-blue-800">Para cambiar tu propia contraseña usa <a href="<?= e(url('/cuenta/seguridad')) ?>" class="font-semibold underline">Seguridad de la cuenta</a>.</div><?php endif; ?><div class="mt-4 grid gap-5 sm:grid-cols-2"><div><label class="label" for="password">Nueva contraseña temporal</label><input id="password" name="password" type="password" class="input" autocomplete="new-password" <?= $account['id'] === $user['id'] ? 'disabled' : '' ?>><p class="mt-1 text-[10px] text-slate-400">10+ caracteres, mayúscula, minúscula y número.</p><?= field_error('password') ?></div><div><label class="label" for="password_confirmation">Confirmar contraseña</label><input id="password_confirmation" name="password_confirmation" type="password" class="input" autocomplete="new-password" <?= $account['id'] === $user['id'] ? 'disabled' : '' ?>><?= field_error('password_confirmation') ?></div></div></div><div class="mt-7 flex justify-end gap-2"><a href="<?= e(url('/equipo')) ?>" class="btn-secondary">Cancelar</a><button type="submit" class="btn-primary"><?= icon('check', 'h-4 w-4') ?> Guardar cuenta</button></div></form><aside class="space-y-5"><section class="ios-card p-5"><h2 class="text-sm font-semibold">Permisos conservados</h2><dl class="mt-4 space-y-3 text-xs"><div><dt class="text-slate-400">Rol</dt><dd class="mt-1 font-medium"><?= e(role_label($account['rol'])) ?></dd></div><div><dt class="text-slate-400">Estado</dt><dd class="mt-1 font-medium"><?= $account['activo'] ? 'Activo' : 'Inactivo' ?></dd></div><div><dt class="text-slate-400">Último ingreso</dt><dd class="mt-1 font-medium"><?= $account['last_login_at'] ? format_date($account['last_login_at'], true) : 'Sin ingresos' ?></dd></div></dl></section><?php if (!empty($account['must_change_password'])): ?><div class="rounded-2xl bg-amber-50 p-4 text-[11px] leading-5 text-amber-800 ring-1 ring-amber-100"><strong>Cambio pendiente.</strong> Esta cuenta todavía debe reemplazar su contraseña temporal.</div><?php endif; ?><div class="rounded-2xl bg-slate-50 p-4 text-[11px] leading-5 text-slate-500">La activación o desactivación se gestiona por separado desde el directorio. Los restablecimientos quedan auditados sin guardar la contraseña en el evento.</div></aside></div>
